const {test}=require('node:test'),assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),{execFile}=require('node:child_process');
const design=require('../webDevelopment/design'),{requirements,newWebsitePlan}=require('../webDevelopment/lifecycle');
const {WorkflowService}=require('../webDevelopment/workflow'),{resolveContext}=require('../webDevelopment/context');
const {DraftStore}=require('../webDevelopment/draftStore'),reports=require('../webDevelopment/reports');
const {parseStatus,commitReviewed}=require('../../oneleadq-windows-bridge/gitSafety');
const {mountUpdateRecovery}=require('../../oneleadq-windows-bridge/updateRecovery');
const supplied={businessName:'Verified Studio',description:'Client supplied interior planning and furniture design.',productsServices:'Interior planning;Furniture design',framework:'STATIC_HTML',language:'en',pages:['home','about','services','contact'],website:'https://example.test',websiteType:'INTERIOR',design:{style:'Luxury',primary:'#174bc8'}};
const req=requirements(supplied);
const mapping={clientId:'client',projectId:'site',workspaceId:'fixture',repository:'local://fixture',enabled:true};
function fixture(){const bridge={async request(){return {workspaces:[{id:'fixture',enabled:true,available:true}]}},async workspace(id,suffix){if(suffix==='git/status')return {git:{repository:true,changedFiles:[],clean:true}};if(suffix.startsWith('files?'))return {items:[]};throw new Error('Unexpected privileged call '+suffix);}};return {bridge,service:new WorkflowService({bridge,mappings:[mapping]})};}
test('twenty website types influence brief, pages, CTA and schema suggestions',()=>{assert.equal(design.TYPES.length,20);assert.notDeepEqual(design.websiteType('INTERIOR').pages,design.websiteType('CATALOGUE').pages);assert.notEqual(design.brief(req).cta,design.brief({...req,websiteType:'RESTAURANT'}).cta);assert.throws(()=>design.websiteType('invented'));});
test('bounded design preferences reject unsafe/invalid tokens',()=>{for(const value of [{primary:'red'},{style:'invented'},{animation:'lots'},{instruction:'api_key="credential123"'}])assert.throws(()=>design.preferences(value));assert.equal(design.preferences({density:'Spacious'}).density,'Spacious');});
test('three structurally different variants have desktop/mobile references and bounded revisions',()=>{const variants=design.variants(req);assert.equal(variants.length,3);assert.equal(new Set(variants.map(v=>v.spec.layout)).size,3);assert.equal(new Set(variants.map(v=>v.spec.cards)).size,3);for(const v of variants){assert.equal(v.previews.desktop.width,1280);assert.equal(v.previews.mobile.width,390);assert.match(v.evidence,/not a rendered-site screenshot/);}assert.equal(design.variants(req,2,'blue theme, bigger hero')[0].spec.primary,'#174bc8');});
test('workflow selection/refinement/regeneration invalidate lock and production planning is gated',async()=>{const {service}=fixture();const created=await service.create('client','site',{mode:'CREATE_NEW',requirements:supplied});await assert.rejects(service.act(created.id,'plan'));const first=await service.act(created.id,'generate-designs');await service.act(created.id,'select-design',{variantId:first.designVariants[1].id});await assert.rejects(service.act(created.id,'approve-design',{approved:true,variantId:'wrong'}));const refined=await service.act(created.id,'refine-design',{instruction:'blue theme, bigger hero; mobile simple'});assert.equal(refined.selectedDesignId,undefined);await service.act(created.id,'select-design',{variantId:refined.designVariants[0].id});const locked=await service.act(created.id,'approve-design',{approved:true,variantId:refined.designVariants[0].id});assert.equal(locked.designLock.state,'APPROVED');assert.equal(locked.designLock.layoutSpecification.layout,'poster');await service.act(created.id,'architecture');await assert.rejects(service.act(created.id,'plan'),/analyze/);await service.act(created.id,'analyze');const planned=await service.act(created.id,'plan');assert.ok(planned.plan.length>5);await assert.rejects(service.act(created.id,'plan',{changes:[]}),/design/);});
test('static generation is design-locked, page-specific, canonical and factual',()=>{assert.throws(()=>newWebsitePlan(req,{}));const locked=design.lock(req,design.variants(req)[0]);const plan=newWebsitePlan(req,{},locked);const html=plan.filter(p=>p.file.endsWith('.html'));assert.equal(new Set(html.map(p=>p.content.match(/name="description" content="([^"]+)/)[1])).size,html.length);for(const page of html){assert.match(page.content,/rel="canonical"/);assert.match(page.content,/layout-split/);assert.ok(!/aggregateRating|reviewCount|priceCurrency|years in business/.test(page.content));}assert.match(html[0].content,/"@type":"Service"/);assert.ok(plan.some(p=>p.file==='sitemap.xml'));assert.match(plan.find(p=>p.file==='package.json').content,/node validate-site.js/);});
test('generated static validation catches broken structure/links and duplicate metadata',async t=>{const directory=fs.mkdtempSync(path.join(os.tmpdir(),'oneleadq-integrity-'));t.after(()=>fs.rmSync(directory,{recursive:true,force:true}));for(const p of newWebsitePlan(req,{},design.lock(req,design.variants(req)[0])))fs.writeFileSync(path.join(directory,p.file),p.content);const run=()=>new Promise(resolve=>execFile(process.execPath,['validate-site.js'],{cwd:directory},error=>resolve(!error)));assert.equal(await run(),true);fs.appendFileSync(path.join(directory,'index.html'),'<a href="missing.html">Missing</a><section>');assert.equal(await run(),false);});
test('local repository identity requires explicit matching mapping',async()=>{const {bridge}=fixture();assert.equal((await resolveContext([mapping],'client','site',bridge)).repository,'local://fixture');await assert.rejects(resolveContext([{...mapping,repository:'local://wrong'}],'client','site',bridge));await assert.rejects(resolveContext([],'client','site',bridge),/No approved repository/);});
test('restart draft recovery contains no approval authority and requires all gates again',async t=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'oneleadq-restore-'));t.after(()=>fs.rmSync(dir,{recursive:true,force:true}));const {bridge}=fixture();const service=new WorkflowService({bridge,mappings:[mapping],draftDirectory:dir});const original=await service.create('client','site',{mode:'CREATE_NEW',requirements:supplied});service.get(original.id).commitApprovalId='never-persist';service.get(original.id).designLock={state:'APPROVED'};new DraftStore(dir).save(service.get(original.id));assert.ok(!fs.readFileSync(path.join(dir,original.id+'.json'),'utf8').includes('never-persist'));const restarted=new WorkflowService({bridge,mappings:[mapping],draftDirectory:dir});const restored=restarted.get(original.id);assert.equal(restored.state,'REQUIREMENTS_READY');assert.equal(restored.designLock,undefined);assert.deepEqual(restored.approvals,[]);assert.match(restored.restoreNotice,/RECONFIRMATION REQUIRED/);await assert.rejects(restarted.act(original.id,'approve-commit',{approved:true,approvalId:'never-persist'}));});
test('report data integrity and escaped content: no fabricated metrics or source payloads',()=>{const run={id:'fixture',requirements:req,context:{clientId:'client',projectId:'site'},mode:'CREATE_NEW',state:'VALIDATION_PASSED',plan:[{file:'index.html',reason:'Approved design'}],designLock:design.lock(req,design.variants(req)[0])};run.beforeReport=reports.enrich(run,{issues:[],limitations:[]},'BEFORE');run.afterReport=reports.enrich(run,{filesChanged:['index.html'],issuesRemaining:[],issuesFixed:[],validations:[{commandId:'npm-build',exitCode:0,passed:true}]},'AFTER');for(const phase of ['BEFORE','AFTER']){const html=reports.reportHtml(run,phase);assert.match(html,/OneLeadQ/);assert.match(html,/Verified Studio/);assert.match(html,/NOT MEASURED/);assert.match(html,/DESIGN PREVIEW/);assert.ok(!html.includes('Lighthouse score:'));}run.requirements.businessName='<script>alert(1)</script>';assert.ok(!reports.reportHtml(run,'BEFORE').includes('<script>alert'));});
test('NUL Git status parses rename, spaces, quotes, deletion, unicode and newlines safely',()=>{const raw='R  new name.html\0old name.html\0 M quote"name.html\0 D deleted.html\0?? new\nline.html\0';assert.deepEqual(parseStatus(raw),[{status:'R ',file:'new name.html',originalFile:'old name.html'},{status:' M',file:'quote"name.html'},{status:' D',file:'deleted.html'},{status:'??',file:'new\nline.html'}]);assert.throws(()=>parseStatus('R  missing.html\0'));});
test('failed commit restores prior partial staging and preserves unrelated staging/working files',async()=>{
 const before='100644 '+'a'.repeat(40)+' 0\treviewed name.html\0',staged='100644 '+'b'.repeat(40)+' 0\treviewed name.html\0';let index=before;const unrelated='unchanged-user-index-entry',working='new working content';const commands=[];
 const run=async(_,args,input)=>{commands.push(args);if(args[0]==='ls-files')return index;if(args[0]==='rev-parse')return 'same-head';if(args[0]==='add'){index=staged;return '';}if(args[0]==='diff')return 'one reviewed file';if(args[0]==='commit')throw new Error('Simulated commit failure');if(args[0]==='update-index'){index=input;return '';}throw new Error('Unexpected command');};
 await assert.rejects(commitReviewed(run,'simulated-repository',['reviewed name.html'],'Will fail'),/staging restored/);assert.equal(index,before);assert.equal(unrelated,'unchanged-user-index-entry');assert.equal(working,'new working content');assert.ok(commands.filter(a=>a[0]==='add')[0].includes('--'));assert.ok(!commands.some(a=>['reset','restore','clean','push'].includes(a[0])));
});
test('update recovery restores only owned unchanged writes and preserves user edits/index/HEAD',async t=>{
 const root=fs.mkdtempSync(path.join(os.tmpdir(),'oneleadq-recovery-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));const routes=new Map(),app={post(route,handler){routes.set(route,handler);}};let head='original-head',index='original-index';
 const journal=mountUpdateRecovery(app,{getApprovedWorkspace:id=>id==='fixture'?{path:root}:null,resolveSafePath:(_,file)=>({workspaceRoot:root,targetPath:path.join(root,file)}),runGit:async(_,args)=>args[0]==='rev-parse'?head:index});
 const file=path.join(root,'page.html');fs.writeFileSync(file,'original');const operationId=await journal.capture({workspaceId:'fixture',file:'page.html',oldContent:'original',newContent:'applied'});fs.writeFileSync(file,'applied');journal.applied(operationId);
 const rollback=async()=>{let status=200,result;await routes.get('/recovery/updates/:operationId/rollback')({params:{operationId},body:{approved:true,workspaceId:'fixture'}},{status(v){status=v;return this},json(v){result=v}});return {status,result};};
 fs.writeFileSync(file,'user edit');assert.equal((await rollback()).status,409);assert.equal(fs.readFileSync(file,'utf8'),'user edit');fs.writeFileSync(file,'applied');head='changed';assert.equal((await rollback()).status,409);head='original-head';index='user staged';assert.equal((await rollback()).status,409);index='original-index';assert.equal((await rollback()).result.restored,true);assert.equal(fs.readFileSync(file,'utf8'),'original');assert.equal((await rollback()).status,409);
});
test('index recovery retains all prior conflict stages and removes only newly staged reviewed entries',()=>{const {indexRestore}=require('../../oneleadq-windows-bridge/gitSafety');const lines=[1,2,3].map(stage=>`100644 ${String(stage).repeat(40)} ${stage}\tconflict.html`).join('\0')+'\0';const payload=indexRestore(lines,['conflict.html','new.html']);assert.ok(payload.startsWith(lines));assert.ok(payload.endsWith('0 '+'0'.repeat(40)+'\tnew.html\0'));});
test('schema JSON is not a credential URL, real credential URLs remain blocked',()=>{const {hasSecret}=require('../webDevelopment/safety');assert.equal(hasSecret('{"@context":"https://schema.org","@graph":[{"@type":"Organization"}]}'),false);assert.equal(hasSecret('https://username:password@example.test'),true);});
test('explicit regeneration invalidates design lock, selection and architecture',async()=>{const {service}=fixture();const run=await service.create('client','site',{mode:'CREATE_NEW',requirements:supplied});const first=await service.act(run.id,'generate-designs');await service.act(run.id,'select-design',{variantId:first.designVariants[0].id});await service.act(run.id,'approve-design',{approved:true,variantId:first.designVariants[0].id});await service.act(run.id,'architecture');const next=await service.act(run.id,'generate-designs');assert.equal(next.designVariants.length,3);assert.equal(next.designRevision,2);assert.equal(next.designLock,undefined);assert.equal(next.architecture,undefined);assert.equal(next.selectedDesignId,undefined);assert.equal(next.state,'DESIGN_VARIANTS_READY');});
test('batch failure recovers only creations confirmed in that operation and fails closed',async()=>{
 const {service,bridge}=fixture();let proposals=0,writes=0;const recovered=[];const request=bridge.request.bind(bridge),workspace=bridge.workspace.bind(bridge);
 bridge.request=async(url,body)=>{if(url.startsWith('/create/approvals/')){writes++;if(writes===2)throw Object.assign(new Error('Synthetic second-file failure'),{status:409});return {created:true,operationId:'first-owned-operation'};}if(url.startsWith('/create/operations/')){recovered.push(body);return {rolledBack:true};}return request(url,body);};
 bridge.workspace=async(id,suffix,body)=>suffix==='create/propose'?{approvalId:'proposal-'+(++proposals)}:workspace(id,suffix,body);
 const run=await service.create('client','site',{mode:'CREATE_NEW',requirements:supplied});const variants=await service.act(run.id,'generate-designs');await service.act(run.id,'select-design',{variantId:variants.designVariants[0].id});await service.act(run.id,'approve-design',{approved:true,variantId:variants.designVariants[0].id});await service.act(run.id,'architecture');await service.act(run.id,'analyze');await service.act(run.id,'plan');const proposed=await service.act(run.id,'propose-files');await assert.rejects(service.act(run.id,'approve-files',{approved:true,approvalIds:proposed.approvals.slice(0,2).map(a=>a.approvalId)}));const result=service.get(run.id);assert.equal(result.state,'FAILED');assert.equal(result.filesChanged.length,0);assert.equal(recovered.length,1);assert.equal(recovered[0].approved,true);assert.deepEqual(result.batch.recovered,[proposed.approvals[0].file]);
});
test('draft persistence rejects plaintext credentials before writing anything',t=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'oneleadq-no-credentials-'));t.after(()=>fs.rmSync(dir,{recursive:true,force:true}));const store=new DraftStore(dir);assert.throws(()=>store.save({id:'fixture',context:{clientId:'client',projectId:'site'},mode:'CREATE_NEW',requirements:{description:'password=do-not-store'}}),/Sensitive/);assert.equal(fs.readdirSync(dir).length,0);});
test('CTA foreground contrast follows approved primary colour',()=>{assert.equal(design.buttonInk('#ffffff'),'#000000');assert.equal(design.buttonInk('#000000'),'#ffffff');const v=design.variants({...req,design:{primary:'#ffffff'}})[0];assert.equal(v.spec.buttonInk,'#000000');});
test('repository identity never reflects filesystem roots or credential-bearing remote labels',async()=>{const {bridge}=fixture();for(const repository of ['https://username:password@example.test/repo','https://credential@example.test/repo','D:/private/workspace','/private/workspace'])await assert.rejects(resolveContext([{...mapping,repository}],'client','site',bridge));});
